"""Reproducible additive-ID FTB Quests 2101.1.36 campaign. No player data writes."""
from pathlib import Path
from presentation import POSITIONS, ICONS, revise
import hashlib, json, re

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'output/ftb-campaign/quests'
QUESTS = []
CHAPTERS = [
 ('survival','Первые шаги','First Steps','minecraft:iron_pickaxe'),
 ('create','Мастерская Create','The Create Workshop','create:cogwheel'),
 ('geology','Геологическая разведка','Geological Survey','createcityexpansioncore:magnetic_analyzer'),
 ('city','Город и территория','City and Territory','createcityexpansioncore:city_pylon'),
 ('mine','Промышленная шахта','Industrial Mining','createcityexpansioncore:mine_controller'),
 ('chunks','Загрузка чанков • дополнительно','Chunk Loading • Optional','createcityexpansioncore:chunk_loader'),
]
def uid(key):
    # Positive, fixed 64-bit IDs; never dependent on ordering or translated copy.
    return f'{int.from_bytes(hashlib.sha256(("ccec-campaign-v1:"+key).encode()).digest()[:8],"big") & 0x7fffffffffffffff:016X}'
def q(ch,key,ru,en,deps,items,body_ru,body_en,side=False):
    QUESTS.append(dict(ch=ch,key=key,ru=ru,en=en,deps=deps.split() if deps else [],
        items=items.split() if items else [],body_ru=body_ru,body_en=body_en,side=side))

# The spine teaches prerequisites. Side branches never gate the next chapter.
q('survival','welcome','Ваш промышленный путь','Your Industrial Journey','','','Начните с выживания, затем освойте Create, разведайте месторождение и постройте городскую шахту. Центральная линия ведёт вперёд; боковые ветки позволяют углубиться. Команда FTB Quests делит прогресс книги, а город CCEC управляет территорией: это разные объединения. Ручные отметки подтверждайте после практики.','Start with survival, learn Create, survey a deposit and build a city mine. The central path leads forward; side branches offer deeper learning. An FTB Quests team shares book progress, while a CCEC city manages territory: they are separate groups. Complete manual checks after practice.')
q('survival','wood','Дерево и доски','Wood and Planks','welcome','','Срубите доступное дерево и превратите часть древесины в доски. Порода не важна: используйте местные ресурсы. Сохраните несколько брёвен для угля и будущих корпусов Create.','Chop a nearby tree and turn some logs into planks. Any local wood is suitable. Keep a few logs for charcoal and future Create casings.')
q('survival','tools','Верстак и первая кирка','Workbench and First Pickaxe','wood','minecraft:crafting_table minecraft:wooden_pickaxe','Верстак открывает полноценные рецепты, а деревянная кирка позволяет добыть камень. Сделайте оба предмета. Инструменты остаются у вас: книга проверяет наличие и ничего не забирает.','A crafting table unlocks full crafting recipes; a wooden pickaxe lets you mine stone. Make both. Tools remain yours: the book checks ownership without consuming anything.')
q('survival','stone','Каменный инструмент','Stone Tools','tools','minecraft:stone_pickaxe','Добудьте булыжник деревянной киркой и изготовьте каменную. Ею можно добыть железную руду; деревянная для этого не подходит. Не тратьте первое железо, пока не подготовлена печь.','Mine cobblestone with the wooden pickaxe and make a stone pickaxe. It can harvest iron ore; a wooden pickaxe cannot. Prepare a furnace before spending your first iron.')
q('survival','food','Еда перед походом','Food Before Exploring','tools','','Найдите доступную пищу и приготовьте её, если это необходимо. Следите за голодом: без достаточного питания труднее восстанавливать здоровье. Подготовьте небольшой запас перед походом за рудой; определённое блюдо не требуется.','Find available food and cook it when necessary. Hunger affects health regeneration. Prepare a small supply before mining; no particular meal is required.')
q('survival','furnace','Печь','A Furnace','stone','minecraft:furnace','Соберите печь из булыжника. Верхняя ячейка принимает сырьё, нижняя — топливо, справа появляется результат. Эта простая установка даст первое железо и приготовит еду.','Craft a furnace from cobblestone. The top slot takes ingredients, the bottom takes fuel, and the output appears on the right. This simple machine provides your first iron and cooks food.')
q('survival','fuel','Топливо для плавки','Fuel for Smelting','furnace','','Подготовьте уголь, древесный уголь или другое подходящее топливо. Древесный уголь получается обжигом брёвен и помогает, когда поблизости нет угольной руды. Сопоставляйте запас топлива с небольшой текущей задачей.','Prepare coal, charcoal or another suitable fuel. Smelting logs produces charcoal when coal ore is scarce. Match your fuel supply to the small batch you actually need.')
q('survival','rawiron','Первое сырое железо','Your First Raw Iron','stone','minecraft:raw_iron','Найдите железную руду и добудьте её каменной киркой или лучше. Освещайте путь и оставляйте безопасный выход. Ванильное сырое железо отличается от промышленного сырья CCEC: у них разные производственные цепочки.','Find iron ore and harvest it with a stone pickaxe or better. Light your route and keep a safe exit. Vanilla raw iron and CCEC industrial ore belong to different processing chains.')
q('survival','iron','Первое выплавленное железо','Your First Smelted Iron','rawiron furnace fuel food','minecraft:iron_ingot','Переплавьте сырое железо в печи. Получение слитка открывает мастерскую Create. Автоматическая проверка видит предмет, а не историю его производства; выполните плавку самостоятельно, чтобы освоить процесс.','Smelt raw iron in your furnace. Obtaining an ingot opens the Create workshop. Automatic detection checks the item rather than its production history; perform the smelting yourself to learn the process.')

V = [
('bed','Кровать и точка возрождения','Bed and Respawn Point','food','','Изготовьте кровать любого цвета и используйте её в безопасном месте. Сон помогает пережить ночь, а установленная точка возрождения сокращает путь после смерти. В Незере и Крае кровати взрываются.','Make a bed of any colour and use it somewhere safe. Sleep helps you survive the night and sets a convenient respawn point. Beds explode in the Nether and the End.'),
('torches','Свет в шахте','Lighting the Mine','fuel','minecraft:torch','Факелы помогают ориентироваться и освещать рабочее место. Освещайте проходы постепенно и отмечайте развилки, чтобы безопасно вернуться с ресурсами.','Torches help navigation and illuminate work areas. Light passages as you explore and mark junctions to find your way home.'),
('shield','Щит и безопасный бой','Shield and Safer Combat','iron','minecraft:shield','Щит полезен против многих атак, но не заменяет укрытие и осторожность. Изучите блокирование на безопасной площадке; для квеста не требуется убивать заданное число существ.','A shield blocks many attacks but does not replace cover and caution. Practise blocking in a safe area; no creature kill quota is required.'),
('bucket','Ведро: вода под рукой','A Bucket for Water','iron','minecraft:bucket','Ведро переносит жидкости и пригодится для хозяйства, спасения от падения и механизмов. Попрактикуйтесь с водой рядом с базой, прежде чем рассчитывать на неё в опасном месте.','A bucket moves fluids and helps with farming, fall recovery and machinery. Practise using water near your base before relying on it in danger.'),
('farm','Первая грядка','Your First Crop Field','food','','Подготовьте пашню рядом с водой и посадите доступную культуру. Свет и защита от вытаптывания важнее размера фермы. Соберите первый урожай и сохраните часть для повторной посадки.','Prepare farmland near water and plant an available crop. Light and protection from trampling matter more than size. Harvest once and save some crops or seeds for replanting.'),
('animals','Животные без лишнего расхода','Keeping Animals','farm','','Устройте загон и изучите подходящую пищу для выбранных животных. Разведение даёт возобновляемые продукты, но большая популяция нагружает сервер. Начните с небольшой пары.','Build a pen and learn which food your animals accept. Breeding provides renewable supplies, but large populations burden the server. Start with a small pair.'),
('fishing','Спокойная рыбалка','A Quiet Fishing Trip','food','minecraft:fishing_rod','Удочка даёт дополнительный источник пищи. Выберите безопасный берег и попробуйте поймать рыбу. Рыбалка — необязательное занятие, а не обязательный источник редких зачарований.','A fishing rod offers another food source. Choose a safe bank and catch a fish. Fishing is optional recreation, not a required hunt for rare enchantments.'),
('compass','Компас и координаты','Compass and Coordinates','iron','minecraft:compass','Обычный компас в Верхнем мире указывает к мировому спавну, а не автоматически к вашей базе. Запишите координаты мастерской и разведки. Позже компас станет компонентом анализатора.','A normal compass points toward world spawn in the Overworld, not automatically toward your base. Record workshop and survey coordinates. A compass later becomes an analyzer component.'),
('boat','Исследование по воде','Exploring by Water','wood','','Сделайте лодку из доступной древесины и исследуйте ближайший безопасный водоём. Возьмите еду и запишите координаты возвращения. Никакой обязательной дальности путешествия нет.','Craft a boat from available wood and explore nearby safe waters. Bring food and record your return coordinates. No travel-distance quota is required.'),
('armor','Броня для экспедиции','Armour for Expeditions','iron','minecraft:iron_chestplate','Железный нагрудник повышает защищённость при разведке. Подготовьте броню по необходимости и следите за прочностью. Полный дорогой комплект не нужен для открытия Create.','An iron chestplate improves expedition safety. Equip armour as needed and watch durability. A full expensive set is not required to unlock Create.'),
('shears','Ножницы и шерсть','Shears and Wool','iron','minecraft:shears','Ножницы позволяют получать шерсть, сохраняя овец. Это удобно для кроватей и декоративных проектов. Дайте овцам доступ к траве для восстановления шерсти.','Shears collect wool without killing sheep. Wool helps with beds and decoration. Give sheep access to grass so their wool can regrow.'),
('storage','Порядок в мастерской','An Organised Workshop','tools','minecraft:chest','Разделите личные вещи, сырьё и готовые компоненты. Подписанные небольшие сундуки помогают увидеть нехватку материалов и избежать случайного расхода важных деталей.','Separate personal equipment, raw materials and finished components. Small labelled chests reveal shortages and prevent accidental use of important parts.'),
('safety','Безопасная добыча','Safer Mining','torches','','Не копайте прямо под собой и над собой. Проверяйте лаву, освещение и путь отхода. Подготовьте запасную кирку и складывайте ценные находки перед опасной разведкой.','Avoid digging straight down or straight up. Watch for lava and keep an illuminated escape route. Bring a spare pickaxe and store valuables before risky exploration.'),
('redstone','Первый редстоун','Your First Redstone','iron','minecraft:redstone','Редстоун нужен для электрических схем и компонентов. Для добычи редстоуновой руды используйте железную кирку или лучше. Позже сигналы помогут управлять механизмами Create.','Redstone supports circuits and components. Harvest redstone ore with an iron pickaxe or better. Signals later help control Create machinery.'),
('nether','Безопасный выход в Незер','A Safe Nether Visit','iron','','Подготовьте портал, еду, негорючие блоки и безопасное укрытие у выхода. Для нагрева Create понадобится найти всполоха. Эта ветка не требует бастиона, незерита или редкого шаблона.','Prepare a portal, food, nonflammable blocks and shelter near the exit. Create heating requires finding a blaze. This branch requires no bastion, netherite or rare upgrade template.'),
('enchant','Зачем нужны зачарования','Why Enchant Equipment','iron','','Стол зачарования улучшает подходящее снаряжение за опыт и лазурит. Изучите влияние книжных полок и сохраните достаточно места вокруг стола. Зачарования помогают исследованию, но не заменяют производство.','An enchanting table improves suitable equipment using experience and lapis. Learn how bookshelves affect it and leave proper clearance. Enchantments help exploration without replacing production.'),
('anvil','Ремонт и объединение','Repairing and Combining','enchant','minecraft:anvil','Наковальня ремонтирует и объединяет совместимые предметы за опыт. Цена повторных работ растёт, поэтому планируйте улучшения заранее. Книга не выдаёт зачарованные книги в награду.','An anvil repairs and combines compatible equipment at an experience cost. Repeated work becomes more expensive, so plan upgrades. This campaign does not reward enchanted books.'),
('brewing','Основы зельеварения','Brewing Basics','nether','','Изучите стойку, топливо и последовательность ингредиентов по рецептам. Начните с одного полезного зелья, например огнестойкости для опасных работ. Ни одно зелье не обязательно для открытия города.','Learn the brewing stand, fuel and ingredient sequence. Start with one useful potion, such as fire resistance for hazardous work. No potion is required to unlock cities.'),
('villagers','Жители и рабочие места','Villagers and Workstations','food','','Изучите связь профессии жителя с рабочим блоком и условия обновления предложений. Защитите поселение и оставьте доступ к рабочим местам. Не требуется строить огромный торговый зал.','Learn how professions depend on workstations and how offers refresh. Protect the settlement and keep workstations accessible. A huge trading hall is unnecessary.'),
('bees','Пчёлы и опыление','Bees and Pollination','farm','','Пчёлы полезны для хозяйства. Изучите безопасный сбор продуктов улья и роль дыма перед взаимодействием. Сохраните цветы рядом и не разрушайте гнездо без подготовки.','Bees support a productive farm. Learn safe harvesting and how smoke affects hive interactions. Keep nearby flowers and prepare before moving a nest.'),
('explore','Экспедиция с возвращением','An Expedition and a Return','compass','','Выберите интересный биом или постройку, подготовьте снаряжение и вернитесь домой. Цель — научиться планировать путь, а не пройти случайное число блоков.','Choose an interesting biome or structure, prepare equipment and return home. The goal is route planning rather than an arbitrary distance.'),
('end','Дальняя цель: Край','A Distant Goal: The End','nether','','Крепость и Край — отдельная приключенческая цель. Подготовьте средства поиска, безопасный путь назад и снаряжение. Победа над драконом не блокирует промышленное развитие.','The stronghold and the End are optional adventure goals. Prepare locating tools, equipment and a safe return plan. Defeating the dragon does not gate industrial progress.'),
]
for k,r,e,d,i,br,be in V:q('survival',k,r,e,d,i,br,be,True)

q('create','ponder','Учиться по рецептам и Ponder','Learning with Recipes and Ponder','iron','','Откройте рецепт андезитового сплава в JEI и демонстрацию пресса в Ponder. Рецепты сборки могут отличаться от роликов. Проверяйте входы, выходы, привод, скорость и нагрев перед строительством.','Open the andesite alloy recipe in JEI and the press demonstration in Ponder. Pack recipes can differ from videos. Check inputs, outputs, drive, speed and heat before building.')
q('create','alloy','Андезитовый сплав','Andesite Alloy','ponder','create:andesite_alloy','Получите первый сплав по JEI. Он нужен для валов и ранних механизмов. Готовьте материалы под конкретную установку; большой запас сам по себе не улучшает производство.','Obtain your first alloy using JEI. It supports shafts and early machines. Prepare materials for a particular build rather than stockpiling without purpose.')
q('create','casing','Андезитовый корпус','Andesite Casing','alloy','create:andesite_casing','Изучите обработку подходящего бревна сплавом в мире. Корпуса входят в рецепты механизмов. Оставьте вокруг мастерской пространство для обслуживания и будущего подключения машин.','Learn how alloy is applied to a suitable log in the world. Casings are machine ingredients. Leave room for maintenance and future connections.')
q('create','wheel','Первое водяное колесо','Your First Water Wheel','casing','create:water_wheel','Установите колесо и организуйте поток по Ponder. Убедитесь, что оно вращается. Предметная задача проверяет наличие колеса; рабочую установку проверяйте сами.','Install the wheel and arrange water flow using Ponder. Confirm that it rotates. The item task checks possession; inspect the operating build yourself.')
q('create','shafts','Валы и шестерни','Shafts and Cogwheels','wheel','create:shaft create:cogwheel','Подведите вращение к месту будущего пресса. Валы работают вдоль оси, а шестерни соединяют подходящие передачи. Проверяйте ориентацию и направление по участкам.','Bring rotation to your future press. Shafts transmit along their axis and cogwheels connect compatible drives. Check alignment and direction section by section.')
q('create','stress','Скорость и нагрузка','Speed and Stress','shafts','','Большая скорость повышает производительность и нагрузку многих машин. При перегрузке сеть останавливается. Отсоедините лишние потребители или увеличьте мощность источника; шестерни меняют скорость, но не создают мощность из ничего.','Higher speed increases throughput and the stress of many machines. An overstressed network stops. Remove excess consumers or improve generation; gearing changes speed without creating power.')
q('create','press','Пресс и депо','Press and Depot','stress','create:mechanical_press create:depot','Поставьте депо под прессом и подключите вращение. Выполните одну операцию с подходящей заготовкой. Начните с ручной подачи: так легче отличить ошибку рецепта от ошибки автоматизации.','Place a depot under a driven press and process one suitable ingredient. Start with manual feeding to distinguish recipe errors from automation errors.')
q('create','sheets','Листы для механизмов','Sheets for Machinery','press','create:iron_sheet create:copper_sheet','Получите железный и медный листы по рецептам сборки. Они нужны для анализатора и других деталей. Храните листы отдельно от слитков, чтобы видеть доступный запас компонентов.','Produce iron and copper sheets using pack recipes. They support the analyzer and other components. Store sheets separately from ingots to track usable parts.')
q('create','mixer','Смеситель и чаша','Mixer and Basin','sheets','create:mechanical_mixer create:basin','Разместите смеситель над чашей по Ponder и обеспечьте необходимую скорость. Проверьте рецепт: некоторые смеси требуют жидкость или нагрев. Чаша сама по себе эти условия не обеспечивает.','Place the mixer above a basin using Ponder and supply the required speed. Some recipes need fluids or heat; a basin alone cannot provide those conditions.')
q('create','automation','Первая автоматическая операция','Your First Automated Operation','mixer','','Соберите небольшую линию обработки: подача заготовки, работа механизма, получение результата. Лента может перемещать заготовку через пресс. Проверьте остановку при заполненном выходе; большая линия пока не нужна.','Build a small processing line: feed a workpiece, process it and collect the result. A belt can move a workpiece through a press. Check behaviour when output fills; a large factory is unnecessary.')
q('create','burner','Нагрев со всполохом','Heating with a Blaze','mixer','create:blaze_burner','Изготовьте пустую горелку и захватите всполоха по Ponder. Подготовьте безопасную экспедицию в Незер. Для нагретого смешивания горелке нужно подходящее топливо; простое размещение не гарантирует требуемый нагрев.','Craft an empty burner and capture a blaze following Ponder. Prepare a safe Nether expedition. Heated mixing needs suitable burner fuel; placement alone does not guarantee the required heat.')
q('create','brass','Первая латунь','Your First Brass','burner automation','create:brass_ingot','Смешайте медь и цинк с нагревом по JEI. Латунь открывает более точные механизмы и механические сборщики. Не подменяйте рецепт сборки рецептом из другой версии.','Mix copper and zinc with heat according to JEI. Brass unlocks precision equipment and mechanical crafters. Follow this pack rather than recipes from another version.')
q('create','tube','Электронная лампа','Electron Tube','brass','create:electron_tube','Подготовьте полированный розовый кварц и остальные компоненты по JEI. Лампа нужна анализатору и управляющим деталям. Латунь завершает учебный маршрут Create, но не является ингредиентом анализатора, если её нет в рецепте.','Prepare polished rose quartz and other JEI ingredients. Electron tubes support the analyzer and control components. Brass completes the Create learning path; it is not an analyzer ingredient unless the recipe says so.')

# Every non-logistics Create family has an optional practical branch.
C = [
('wrench','Ключ и очки инженера','Wrench and Engineer Goggles','casing','create:wrench create:goggles','Ключ помогает настраивать и переставлять механизмы, очки показывают дополнительные сведения. Осмотрите привод и потребитель, чтобы связать показания с устройством машины.','The wrench adjusts machinery; goggles reveal extra information. Inspect a source and consumer to connect readings with the machine layout.'),
('gearing','Передаточное отношение','Gear Ratios','shafts','create:large_cogwheel create:gearbox','Сравните большую и малую шестерни и поворот через редуктор. Изменяя скорость, следите за направлением и нагрузкой. Сначала испытайте передачу без дорогого оборудования.','Compare large and small cogwheels and a gearbox turn. Track direction and stress when changing speed. Test gearing before attaching expensive equipment.'),
('clutch','Отключать и реверсировать','Disconnecting and Reversing','shafts','create:clutch create:gearshift','Муфта отключает передачу сигналом, переключатель меняет направление. Сделайте безопасный выключатель для обслуживаемой машины. Реверс не подходит каждому потребителю.','A clutch disconnects transmission with redstone; a gearshift reverses it. Build a maintenance switch. Not every machine benefits from reversing.'),
('wind','Ветряная мельница','A Windmill','shafts','create:windmill_bearing create:white_sail','Соберите подшипник и паруса по Ponder. Площадь парусов влияет на доступную мощность в пределах механики. Оставьте свободное пространство для вращения.','Assemble a windmill bearing and sails with Ponder. Sail area affects available capacity within the mechanic limits. Leave clearance for rotation.'),
('largewheel','Большое колесо','A Large Water Wheel','wheel','create:large_water_wheel','Большое колесо позволяет иначе организовать источник вращения. Сверьте условия потока и габариты с Ponder; несколько неправильно установленных источников не исправят передачу.','A large wheel offers another generation layout. Check water conditions and dimensions in Ponder; extra incorrectly installed sources cannot repair a faulty drive.'),
('meters','Измерить сеть','Measuring the Network','stress','create:speedometer create:stressometer','Спидометр показывает скорость, измеритель нагрузки — состояние сети. Снимите показания до и после подключения машины. Это удобнее поиска причины остановки наугад.','A speedometer measures speed and a stressometer reports network load. Compare readings before and after connecting a machine instead of guessing why it stops.'),
('speedcontrol','Регулятор скорости','Rotation Speed Controller','brass','create:rotation_speed_controller','Регулятор помогает задать удобную скорость. Установите его с нужной передачей по Ponder. Он не заменяет генератор: после регулировки проверяйте нагрузку.','The controller sets a convenient speed. Install it with the required gearing using Ponder. It is not a generator: check stress after adjustment.'),
('mill','Жернов','Millstone','shafts','create:millstone','Жернов выполняет доступные рецепты измельчения. Выберите один рецепт и проверьте результат небольшой партии. Не путайте набор его рецептов с дробильными колёсами.','A millstone performs its available milling recipes. Test one recipe with a small batch. Its recipe set differs from crushing wheels.'),
('saw','Механическая пила','Mechanical Saw','shafts','create:mechanical_saw','Пила обрабатывает подходящие заготовки и участвует в работе с деревьями. Изучите ориентацию и выбор рецепта. Испытайте один материал перед созданием лесозаготовки.','A saw processes suitable workpieces and can work with trees. Learn orientation and recipe selection. Test one material before building a tree farm.'),
('fan','Вентилятор как обработчик','Fan Processing','shafts','create:encased_fan','Поток вентилятора переносит свойства среды к предметам. Направление и среда определяют обработку. Изучите четыре режима в соседних заданиях; простое вращение не выполняет все рецепты.','Fan airflow carries processing effects to items. Direction and the medium determine the process. Explore four modes nearby; rotation alone does not enable every recipe.'),
('wash','Промывка','Bulk Washing','fan','','Пропустите воздушный поток через воду и обработайте совместимый предмет по JEI. Убедитесь, что предмет находится в рабочем потоке. Промывка Create не заменяет смешивание концентрата CCEC.','Pass airflow through water and process a compatible JEI ingredient. Keep the item inside the effective flow. Create washing does not replace CCEC concentrate mixing.'),
('smoke','Копчение потоком','Bulk Smoking','fan','','Изучите копчение вентилятором через подходящую среду по Ponder. Испытайте небольшой пищевой рецепт. Проверяйте результат и не размещайте горючие детали возле опасной среды.','Study fan smoking through the appropriate medium in Ponder. Test a small food recipe. Inspect the result and keep flammable parts away from hazardous media.'),
('blast','Обжиг потоком','Bulk Blasting','fan','','Создайте режим обжига по Ponder и выберите совместимый рецепт JEI. Организуйте безопасное удержание предметов возле горячей среды. Не все рецепты печи взаимозаменяемы с другими режимами.','Set up blasting with Ponder and choose a compatible JEI recipe. Keep items safely positioned near the hot medium. Processing modes are not interchangeable for every recipe.'),
('haunt','Обработка огнём душ','Bulk Haunting','fan','','Изучите преобразования потоком через огонь душ. Проверьте один рецепт в JEI и сравните исходный предмет с результатом. Это отдельная операция со своим набором рецептов.','Explore transformations using airflow through soul fire. Check one JEI recipe and compare input with output. Haunting has its own recipe set.'),
('crafter','Механические сборщики','Mechanical Crafters','brass','create:mechanical_crafter','Сборщики выполняют большие рецепты Create и CCEC. Расставьте сетку и направьте выходы к общей точке по Ponder. Размер рецепта и направление сборки важны так же, как ингредиенты.','Crafters execute large Create and CCEC recipes. Arrange the grid and point outputs toward one collection point using Ponder. Recipe dimensions and assembly direction matter alongside ingredients.'),
('crushing','Дробильные колёса','Crushing Wheels','crafter','create:crushing_wheel','Пара колёс дробит совместимые материалы. Подключите правильное встречное вращение и испытайте одну заготовку. Держитесь подальше от рабочей зоны.','A pair of wheels crushes compatible materials. Supply the correct opposing rotation and test one workpiece. Stay clear of the operating area.'),
('deployer','Механическая рука','Deployer','brass','create:deployer','Деплойер применяет предмет или инструмент к цели. Настройте ориентацию и режим по Ponder, затем испытайте простую операцию. Для последовательной сборки ему нужны конкретные компоненты каждого шага.','A deployer uses an item or tool on a target. Configure orientation and mode using Ponder, then test a simple operation. Sequenced assembly requires the correct component at every step.'),
('precision','Точный механизм','Precision Mechanism','deployer','create:precision_mechanism','Пройдите последовательную сборку по JEI: соблюдайте порядок операций и число повторений. Незавершённая деталь не является готовым механизмом. Подготовьте резерв на возможные побочные результаты рецепта.','Follow the JEI sequence in order for the required number of loops. An incomplete component is not a finished mechanism. Allow for any alternative recipe outcomes.'),
('superheat','Перегрев горелки','Superheating a Burner','burner','create:blaze_cake','Пирог для всполоха позволяет получить перегрев для соответствующих рецептов. Изучите производство пирога и потребность в топливе. Обычный нагрев и перегрев — разные условия.','Blaze cake enables superheating for recipes that require it. Study cake production and fuel use. Heated and superheated are distinct recipe conditions.'),
('compacting','Уплотнение в чаше','Basin Compacting','press','create:basin','Пресс над чашей выполняет уплотнение по доступным рецептам. Проверьте количество ингредиентов, жидкость и нагрев. Депо и чаша служат разным операциям.','A press above a basin performs compacting recipes. Check ingredient amounts, fluids and heat. A depot and a basin support different operations.'),
('pipes','Трубы и насос','Pipes and Pumps','mixer','create:fluid_pipe create:mechanical_pump','Соберите короткую линию воды. Направление насоса зависит от вращения; проверьте его до подключения чаши. Прозрачный участок помогает увидеть движение жидкости.','Build a short water line. Pump direction depends on rotation; verify it before connecting a basin. A transparent section helps inspect fluid movement.'),
('tank','Резервуар жидкости','Fluid Tank','pipes','create:fluid_tank','Резервуар буферизует запас жидкости. Соберите допустимую форму по Ponder и проверьте подключение. Буфер сглаживает расход, но не создаёт жидкость.','A tank buffers fluid supply. Build an allowed shape using Ponder and check connections. A buffer smooths consumption without creating fluid.'),
('spout','Наполнение предметов','Filling Items','pipes','create:spout','Спут заполняет подходящие предметы жидкостью по рецептам. Подайте жидкость сверху и разместите заготовку в рабочем положении по Ponder. Проверяйте обе стороны рецепта.','A spout fills compatible items using recipe fluids. Feed fluid from above and position a workpiece using Ponder. Check both fluid and item requirements.'),
('drain','Опустошение ёмкостей','Emptying Containers','pipes','create:item_drain','Слив извлекает жидкость из совместимых ёмкостей. Подключите выход и проверьте, куда уходит пустой предмет. Сначала испытайте одну ёмкость.','An item drain extracts fluids from compatible containers. Connect the output and check where the empty item goes. Start with one container.'),
('hose','Шланг и источник жидкости','Hose Pulley and Fluid Sources','tank','create:hose_pulley','Шланг работает с жидкостями в мире. Изучите пределы источника и конфигурацию сборки: небольшой водоём не следует считать бесконечным. Не осушайте общие водоёмы без согласования с соседями.','A hose pulley interacts with world fluids. Learn source limits and pack settings: a small pool is not automatically infinite. Coordinate before draining shared waters.'),
('steam','Паровая установка','A Steam Plant','tank burner','create:steam_engine','Паровой двигатель работает с котлом, водой и нагревом. Соберите небольшую установку по Ponder и сравните мощность с нагрузкой. Обеспечьте устойчивое водоснабжение до расширения.','A steam engine needs a boiler, water and heat. Build a small plant using Ponder and compare capacity with load. Secure a steady water supply before expanding.'),
('glue','Склеить конструкцию','Gluing a Contraption','casing','create:super_glue','Суперклей объединяет блоки движущейся конструкции. Выделяйте только нужную область и проверяйте её перед запуском. Случайно приклеенная часть здания может уехать вместе с машиной.','Super glue joins blocks into moving contraptions. Select only the intended area and inspect it before assembly. Accidentally glued building parts may move with the machine.'),
('bearing','Вращающаяся конструкция','Rotating Contraptions','glue','create:mechanical_bearing','Подшипник вращает собранную конструкцию. Оставьте свободную рабочую область и изучите остановку и разборку по Ponder. Начните с маленького безопасного макета.','A mechanical bearing rotates an assembled contraption. Leave clearance and learn stopping and disassembly through Ponder. Start with a small safe prototype.'),
('piston','Механический поршень','Mechanical Piston','glue','create:mechanical_piston create:piston_extension_pole','Поршень перемещает конструкцию вдоль оси; удлинители задают доступный ход. Проверьте свободное пространство и изменение направления привода перед подключением рабочего оборудования.','A piston moves a contraption along its axis; extension poles define travel. Check clearance and drive reversal before adding working equipment.'),
('pulley','Вертикальный подъём','Vertical Lifting','glue','create:rope_pulley','Канатный шкив поднимает и опускает закреплённую конструкцию. Испытайте небольшой груз и безопасную остановку. Не стойте в шахте подъёмника во время первого запуска.','A rope pulley raises and lowers an attached contraption. Test a small platform and safe stopping. Keep clear of its shaft during initial testing.'),
('gantry','Портальная передача','Gantry Motion','glue','create:gantry_shaft create:gantry_carriage','Каретка перемещается по портальному валу. Изучите связь вращения, движения и питания присоединённой конструкции. Планируйте крайние положения и доступ для обслуживания.','A gantry carriage travels along a gantry shaft. Learn how rotation powers travel and attached machinery. Plan end positions and maintenance access.'),
('elevator','Лифт между этажами','An Elevator Between Floors','pulley','','Изучите лифтовый шкив и контакты в Ponder установленной версии. Соберите безопасный двухэтажный макет с остановками. Это необязательная строительная ветка.','Study the installed version’s elevator pulley and contacts in Ponder. Build a safe two-floor prototype with stops. This construction branch is optional.'),
('drill','Бур для обычных блоков','Drilling Ordinary Blocks','shafts','create:mechanical_drill','Бур разрушает подходящие блоки перед собой при работе привода. Он не равен промышленной шахте CCEC, которая использует геологические залежи. Испытайте бур на безопасной площадке.','A powered drill breaks suitable blocks in front of it. It differs from a CCEC industrial mine, which works with geological deposits. Test drilling in a safe area.'),
('harvest','Автоматический урожай','Automatic Harvesting','bearing','create:mechanical_harvester','Комбайн на движущейся конструкции собирает совместимые культуры. Изучите ориентацию, повторную посадку и хранение результата по Ponder. Маленькая ферма проще для диагностики.','A harvester on a moving contraption gathers compatible crops. Study facing, replanting and result storage using Ponder. A small farm is easier to diagnose.'),
('plough','Подготовка земли','Preparing the Ground','bearing','create:mechanical_plough','Плуг помогает обрабатывать землю и убирать подходящие поверхностные блоки. Испытайте его на отдельном участке, чтобы случайно не повредить дорожки и посадки.','A plough prepares land and clears suitable surface blocks. Test it on a separate patch to avoid damaging paths and crops.'),
('roller','Механический каток','Mechanical Roller','bearing','create:mechanical_roller','Каток помогает изменять поверхность под движущейся машиной. Изучите режим, фильтр и расход материала по Ponder. Сначала проверьте короткий участок вне готового города.','A roller changes terrain beneath a moving machine. Study modes, filters and material use in Ponder. Test a short stretch away from finished buildings.'),
('contraption','Остановка и обслуживание','Stopping and Servicing','bearing','','Проверьте сборку, движение, остановку и разборку небольшого механизма. Не все блоки работают одинаково после сборки в конструкцию. Перед сложным проектом испытайте нужный рабочий блок отдельно.','Test assembly, movement, stopping and disassembly on a small contraption. Blocks can behave differently while assembled. Test the intended working block before a complex project.'),
('redcontrol','Редстоун управляет машиной','Redstone Machine Control','clutch','create:redstone_contact','Контакты и муфты помогают связать положение механизма с действием. Создайте понятный ручной останов и испытайте его. Оставьте доступ к выключателю вне зоны движения.','Contacts and clutches link machine position with actions. Build and test a clear manual stop. Keep its switch outside the moving area.'),
('sequencegear','Заданная последовательность движения','Programmed Motion','clutch','create:sequenced_gearshift','Последовательный переключатель выполняет настроенные этапы вращения. Используйте его для повторяемого движения небольшого макета. Он управляет приводом и отличается от последовательной сборки предметов.','A sequenced gearshift runs configured rotation steps. Use it for repeatable prototype movement. Drive sequencing differs from item sequenced assembly.'),
('signals','Сигналы, задержки и импульсы','Signals, Delays and Pulses','redcontrol','','Изучите доступные редстоуновые компоненты Create через JEI и Ponder: задержку, импульс и беспроводной сигнал. Соберите одну управляемую цепь; проверьте поведение при исчезновении сигнала.','Explore Create signal components with JEI and Ponder: delays, pulses and wireless transmission. Build one controlled circuit and test what happens when the signal disappears.'),
('display','Показания на виду','Visible Readings','meters','create:display_link create:display_board','Связь дисплея переносит поддерживаемые показания на совместимый экран. Выберите доступный источник в интерфейсе; не любой блок предоставляет данные. Используйте табло для наблюдения за мастерской.','A display link sends supported readings to a compatible display. Select an available source in its interface; not every block exposes data. Use a board to monitor the workshop.'),
('schematic','Схема для строительства','A Building Schematic','casing','create:schematic_and_quill','Перо со схемой сохраняет выбранную постройку. Перед сохранением проверьте границы области и ориентацию. Схема помогает повторять проект, но не выдаёт материалы.','A schematic and quill saves a selected build. Check selection bounds and orientation before saving. Schematics repeat designs without supplying materials.'),
('cannon','Построить по схеме','Building from a Schematic','schematic','create:schematicannon','Схематическая пушка строит по схеме с подготовленными материалами и топливом. Проверьте список ресурсов, место установки и настройки замены блоков. Начните с небольшого макета.','A schematicannon builds a schematic using supplied materials and fuel. Check the material list, placement and replacement settings. Start with a small prototype.'),
('decoration','Строительные формы Create','Create Building Shapes','casing','','Изучите палитру блоков Create в JEI: камень, окна, ограды, двери и декоративные формы. Оформите небольшой участок мастерской. Декор не обязателен для запуска производства.','Explore Create stone, windows, fences, doors and decorative shapes in JEI. Finish a small workshop area. Decoration does not gate production.'),
('equipment','Инструменты исследователя','Explorer Equipment','brass','','Изучите доступные инструменты Create и их рецепты в JEI, включая строительные и переносные приспособления. Выберите полезный лично вам предмет и испытайте его безопасно. Креативные предметы не являются целями кампании.','Explore available Create tools and recipes in JEI, including building and portable equipment. Choose something useful and test it safely. Creative-only items are not campaign objectives.'),
('foodcreate','Пищевые операции Create','Create Food Processing','wash spout','','Выберите пищевой рецепт Create и проследите весь путь от ингредиентов до готового блюда. Используйте изученные операции смешивания, наполнения или обработки потоком. Не требуется производить большие партии.','Choose a Create food recipe and trace ingredients to the finished meal. Use learned mixing, filling or fan-processing operations. Large batches are unnecessary.'),
]
C.extend([
('handcrank','Ручной привод','Hand Crank','shafts','create:hand_crank','Ручной привод удобен для короткого испытания механизма и аварийной перестановки. Вращайте его вручную, наблюдая направление. Для постоянного производства нужен устойчивый источник мощности.','A hand crank helps with short machine tests and emergency repositioning. Turn it manually and observe direction. Continuous production needs a sustainable power source.'),
('valve','Клапан на трубопроводе','A Pipeline Valve','pipes','create:fluid_valve','Клапан позволяет управлять проходом жидкости. Изучите привод и крайние положения по Ponder. Испытайте перекрытие на небольшой водяной линии перед подключением к котлу.','A valve controls fluid passage. Study its drive and end positions in Ponder. Test shutoff on a small water line before connecting a boiler.'),
('clock','Механические часы','Mechanical Clock','shafts','create:cuckoo_clock','Часы превращают вращение в наглядную декоративную механику. Изучите их работу и установите в мастерской. Это отдельный необязательный проект, не условие промышленного запуска.','A cuckoo clock turns rotation into visible decorative machinery. Learn its behaviour and install one in the workshop. It is an optional project rather than an industrial prerequisite.'),
('backtank','Запас воздуха','An Air Supply','brass','create:copper_backtank','Заправьте воздушный баллон вращением по Ponder. Он используется совместимым снаряжением; следите за остатком воздуха перед погружением. Баллон не является электрической батареей.','Charge a backtank with rotation as shown in Ponder. Compatible equipment uses its air; inspect the remaining supply before diving. A backtank is not an electrical battery.'),
('diving','Подводные работы','Underwater Work','backtank','create:copper_diving_helmet create:copper_diving_boots','Изучите совместную работу шлема, баллона и ботинок. Испытайте комплект у безопасного берега и проверьте воздух. Подготовьте обычный путь выхода из воды на случай ошибки.','Learn how the helmet, backtank and boots work together. Test them near a safe shore and watch the air supply. Keep a normal escape route from the water.'),
('grip','Дотянуться до стройки','Reaching Your Build','brass','create:extendo_grip','Удлинённая рука помогает взаимодействовать с удалёнными блоками. Изучите использование и расход ресурса инструмента. Она удобна при обслуживании, но не даёт прав менять чужую территорию.','An extendo grip helps reach distant blocks. Learn its use and resource consumption. Extra reach helps maintenance but does not grant permission to alter someone else’s land.'),
('potato','Картофельная пушка','Potato Cannon','brass','create:potato_cannon','Изучите доступные боеприпасы и работу инструмента. Испытывайте пушку на безопасной площадке, вдали от игроков и хрупких построек. Она не нужна для получения промышленной шахты.','Study compatible ammunition and how the tool works. Test it safely away from players and fragile builds. A cannon is not needed for industrial mining.'),
('controller','Управление конструкцией','Contraption Controls','contraption','','Изучите контролируемые подшипники и органы управления конструкцией в Ponder. Настройте одну небольшую управляемую постройку и проверьте безопасное отключение. Транспортные и железнодорожные системы рассматриваются отдельно.','Explore controlled bearings and contraption controls in Ponder. Configure a small controllable build and test safe shutdown. Transport and railway systems belong to a separate chapter.'),
])
for k,r,e,d,i,br,be in C:q('create',k,r,e,d,i,br,be,True)

q('geology','analyzer','Магнитный анализатор','Magnetic Analyzer','tube','createcityexpansioncore:magnetic_analyzer','Рецепт использует медные и железные листы, сплав, редстоун, компас и лампу. Прибор помогает выбрать место промышленной добычи. Подготовьте его до выхода на разведку.','The recipe uses copper and iron sheets, alloy, redstone, a compass and an electron tube. The device helps locate industrial extraction sites. Prepare it before surveying.')
q('geology','reading','Первое измерение','Your First Reading','analyzer','','Нажмите ПКМ в воздухе или по блоку. Замер относится к положению игрока. Прибор имеет десять использований и перезаряд; двигайтесь между осмысленными точками, а не расходуйте все измерения на месте.','Right-click in air or on a block. The reading uses the player’s position. The analyzer has ten uses and a cooldown; move between meaningful locations rather than spending every reading at one spot.')
q('geology','anomaly','Найти аномалию','Find an Anomaly','reading','','Вне залежи анализатор сообщает направление и грубую дистанцию до ближайшей доступной аномалии в пределах поиска. Отсутствие результата не доказывает отсутствие ресурсов во всём регионе. Переместитесь и сравните показания.','Outside a deposit, the analyzer reports direction and approximate distance to a nearby anomaly within its search range. An empty result does not prove the entire region lacks resources. Move and compare readings.')
q('geology','deposit','Оценить залежь','Assess the Deposit','anomaly','','Внутри месторождения сравните производственный потенциал, оценку оставшегося запаса и класс размера. Координаты ядра не выдаются напрямую. Ищите подходящую площадку последовательными измерениями.','Inside a deposit, compare production potential, estimated remaining reserves and size class. The core coordinates are not revealed directly. Use successive readings to choose a suitable site.')
q('geology','site','Выбрать площадку','Choose the Site','deposit','','Учитывайте ресурс, потенциал и запас, рельеф, место под шахту, электроснабжение и выход продукции. Запишите координаты и оставьте место для обслуживания. Выбор точки — практическая ручная проверка.','Consider resource type, potential, reserves, terrain, mine space, power and output access. Record coordinates and reserve maintenance space. Site selection is a manual practical check.')
q('city','cityintro','Город: два пути входа','City: Two Ways to Begin','site','','Можно основать собственный город через City Pylon или принять приглашение в существующий. Не нужно создавать отдельный город каждому участнику. Вступающему игроку не требуется крафтить новый пилон.','Found a city through a City Pylon or accept an invitation to an existing city. Each player does not need a separate city. Joining players do not need to craft another pylon.')
q('city','found','Основать или вступить','Found or Join','cityintro','','Основатель изготавливает City Pylon по JEI, ставит его и открывает форму создания города. Для вступления используйте приглашение существующего города. После успешного действия отметьте этот этап; книга не проверяет членство автоматически.','A founder crafts a City Pylon using JEI, places it and opens city creation. Joining players use an existing city’s invitation. Mark this step after success; the book does not automatically detect membership.')
q('city','territory','Территория города','City Territory','found','','Откройте управление территорией и изучите границы. Расширяйте владения только при наличии прав и выполнении условий интерфейса. Это задание знакомит с правилами и не требует покупать ненужные участки.','Open territory management and inspect boundaries. Expand only with the required permissions and interface conditions. This task teaches the rules without requiring unnecessary claims.')
q('city','worldmap','WorldMap: видеть регион','WorldMap: See the Region','territory','','Откройте карту через доступный городской интерфейс. Попробуйте перемещение, масштаб и слои; найдите свой город и площадку. Видимость объектов зависит от данных сервера и прав доступа.','Open the map through the available city interface. Try panning, zooming and layers; locate your city and worksite. Object visibility depends on server data and permissions.')
q('city','roles','Роли и права','Roles and Permissions','found','','Просмотрите участников и доступные им действия. Solo-игрок может изучить это в собственном городе без приглашения второго человека. Команда FTB и город не обязаны иметь одинаковый состав.','Review members and their permitted actions. A solo player can learn this in their own city without inviting anyone. FTB team membership and city membership may differ.')
q('city','project','Подготовка промышленного проекта','Prepare an Industrial Project','worldmap roles','','Проверьте доступ к площадке и необходимым действиям города. Разместите план шахты так, чтобы хватило пространства конструкции, проводам и обслуживанию выхода. При командной игре распределите задачи по материалам и питанию.','Check access to the site and required city actions. Reserve room for the structure, wiring and output maintenance. Teams can divide material preparation and electrical work.')

q('mine','mineplan','От площадки к шахте','From Site to Mine','project','','Шахта объединяет геологию, мультиблок, реальную сеть EE и выдачу продукции. Подготовьте производство деталей до сборки. Create-вращение не заменяет электрическое питание энергетического порта.','A mine combines geology, a multiblock, an actual EE network and output handling. Prepare component production before assembly. Create rotation does not replace electrical power at the mine port.')
q('mine','steel','Сталь для промышленности','Steel for Industry','mineplan','createcityexpansioncore:steel_billet','Проверенный стартовый рецепт смешивает четыре железных слитка, четыре промышленных кокса и негашёную известь с перегревом, получая две заготовки. Изучите в JEI получение кокса и извести. Этот путь позволяет подготовить шахту до её первой добычи.','The verified starter recipe mixes four iron ingots, four industrial coke and quicklime under superheat to produce two billets. Study coke and quicklime recipes in JEI. This path prepares a mine before its first extraction.')
q('mine','components','Обработка промышленных материалов','Processing Industrial Materials','steel','createcityexpansioncore:steel_plate createcityexpansioncore:structural_beam createcityexpansioncore:copper_busbar','Прессуйте и режьте заготовки по JEI. Для корпуса шахты понадобятся также крепёж, техническая керамика и армированный бетон. Проверяйте цепочку каждого ингредиента; книга не выдаёт их вместо производства.','Press and cut materials using JEI. Mine construction also needs fasteners, technical ceramic and reinforced concrete. Trace each ingredient chain; quests do not supply industrial materials as rewards.')
q('mine','assemblyparts','Последовательная сборка деталей','Sequenced Industrial Assembly','components','createcityexpansioncore:heavy_machine_frame createcityexpansioncore:industrial_control_unit','Рама и блок управления собираются последовательными операциями. Рама начинается с андезитового корпуса; блок управления — с точного механизма. Соблюдайте порядок, повторы и промежуточный предмет по JEI. В командной мастерской можно пользоваться общей линией.','The frame and control unit use sequenced operations. A frame starts from an andesite casing; a control unit starts from a precision mechanism. Follow JEI order, loops and intermediate items. Teams may use a shared assembly line.')
q('mine','mineparts','Компоненты мультиблока','Multiblock Components','assemblyparts','createcityexpansioncore:mine_controller createcityexpansioncore:mine_power_port createcityexpansioncore:mine_gateway createcityexpansioncore:mine_frame createcityexpansioncore:technical_block createcityexpansioncore:drill_unit','Подготовьте типы блоков и полное количество по подсказке контроллера. Предметная задача требует по образцу каждого типа, а не весь строительный комплект. Рецепты механической сборки требуют правильно направленной сетки сборщиков.','Prepare block types and full quantities using the controller guide. Item tasks ask for one sample of each type, not the full construction bill. Mechanical crafting needs a correctly directed crafter grid.')
q('mine','footprint','Подготовить место 10×3×10','Prepare a 10×3×10 Site','mineparts','','Размер шахты — 10×3×10; контроллер расположен на среднем уровне передней стороны согласно схеме. Оставьте доступ к шлюзу и две свободные клетки для проводов рядом с энергетическим портом. Сверяйте ориентацию с подсказкой в мире.','The mine is 10×3×10; its controller sits on the middle front layer as shown in the guide. Leave gateway access and two free wiring spaces beside the power port. Check orientation with the in-world guide.')
q('mine','assembled','Собрать и проверить','Assemble and Inspect','footprint','','Соберите конструкцию по руководству контроллера и устраните отмеченные ошибки. Нужны ровно один энергетический порт и один шлюз. Наличие блоков в инвентаре не подтверждает правильную сборку; проверьте состояние контроллера.','Build from the controller guide and fix highlighted errors. Exactly one power port and one gateway are required. Inventory ownership does not prove assembly; inspect the controller state.')
q('mine','eepower','Сеть ElectroEnergetics','An ElectroEnergetics Network','assembled','','Подключите порт к реальной сети EE. Изучите генерацию, соединители, провод и трансформацию напряжения в JEI/Ponder EE. Для работы шахта проверяет напряжение, ток и мощность: одного видимого провода недостаточно. Не используйте креативные источники.','Connect the port to an actual EE network. Study generation, connectors, wire and voltage transformation in EE JEI/Ponder. The mine checks voltage, current and power; a visible wire alone is insufficient. Do not use creative sources.')
q('mine','eemeasure','Измерить питание под нагрузкой','Measure Power Under Load','eepower','electroenergetics:voltmeter electroenergetics:clamp_meter','Используйте измерительные приборы и показания контроллера. Номинал шахты — 500 В и 10 кВт; рабочее окно проверяется отдельно от режима ожидания. Следите за недостатком напряжения и перегрузкой. До запуска сопоставьте источник, проводку и потребитель.','Use electrical instruments and controller readings. Mine nominal demand is 500 V and 10 kW; working load is checked separately from standby. Watch undervoltage and overload. Match generation, wiring and the consumer before startup.')
q('mine','readiness','Готовность к запуску','Ready to Start','eemeasure','','Проверьте сборку, питание, доступную залежь и свободный выход. Выбирайте залежь до ввода в работу: специализация контроллера фиксируется по правилам интерфейса. Не рассчитывайте свободно менять ресурс после запуска.','Check assembly, power, an available deposit and free output. Choose the deposit before commissioning: controller specialisation becomes fixed according to the interface rules. Do not assume unrestricted resource switching after startup.')
q('mine','startmine','Первый запуск','First Startup','readiness','','Запустите шахту через контроллер и наблюдайте переход к рабочему состоянию. Если запуск отклонён, прочитайте причину и исправьте её. Этап подтверждается вручную после фактической работы, а не после изготовления контроллера.','Start the mine through its controller and observe the transition to operation. If rejected, read and resolve the reason. Confirm this step after actual operation rather than merely crafting a controller.')
q('mine','firstoutput','Первая добыча','First Extraction','startmine','','Заберите небольшую партию фактического продукта из выхода. Тип продукции зависит от выбранной залежи, поэтому книга не заставляет добывать именно железо. Проверьте, что запас выхода освобождается и шахта продолжает работать.','Collect a small batch of actual output. The resource depends on the selected deposit, so iron is not mandatory. Clear output space and verify the mine continues working.')
q('mine','diagnose','Диагностика остановок','Diagnosing Stops','firstoutput','','При остановке читайте состояние контроллера: проверьте питание, выход продукции, структуру и залежь. OUTPUT_BLOCKED требует освободить выход; LOW_POWER — проверить сеть под нагрузкой. Не ломайте всю шахту и не меняйте сохранённую геологию ради устранения обычной ошибки.','Read the controller state when operation stops: inspect power, output, structure and deposit. OUTPUT_BLOCKED requires output space; LOW_POWER requires checking the loaded electrical network. Do not dismantle everything or alter saved geology to fix routine faults.')
q('mine','orechain','Переработка железа CCEC','CCEC Iron Processing','firstoutput','','Для железной залежи: сырая руда CCEC → дробление → четыре дроблёные руды с 250 mB воды в концентрат → нагретое смешивание в два слитка. Это отдельная цепочка от ванильного железа и промывки Create. Для другого ресурса изучите его фактический рецепт.','For an iron deposit: CCEC raw ore → crushing → four crushed ore plus 250 mB water into concentrate → heated mixing into two ingots. This differs from vanilla iron and Create washing. For another resource, inspect its actual recipe.',True)
q('chunks','chunkintro','Когда чанки выгружаются','When Chunks Unload','firstoutput','','Удалённая машина может остановиться, если её чанки перестали обрабатываться. Чанклоадер удерживает область загруженной, но не добавляет питание и не освобождает выход. Эта ветка необязательна для завершения шахты.','A distant machine may stop when its chunks are no longer ticking. A chunk loader keeps an area active but does not supply power or clear outputs. This branch is not required to finish the mine.',True)
q('chunks','chunkitem','Чанклоадер CCEC','CCEC Chunk Loader','chunkintro','createcityexpansioncore:chunk_loader','Изготовьте чанклоадер механической сборкой по JEI: используются стальные пластины, балки, медная шина и крепёж. Ставьте только там, где нужна постоянная работа, а не по всей территории города.','Craft a loader with mechanical crafting using JEI: steel plates, beams, a copper busbar and fasteners. Place it only where continuous operation is needed rather than throughout the city.',True)
q('chunks','chunklimits','Один чанк и личный лимит','One Chunk and a Personal Limit','chunkitem','','Устройство удерживает свой чанк 16×16, а не произвольный радиус. Лимит — три устройства на игрока; командный прогресс книги его не увеличивает. Покажите границы чанков через F3+G и проверьте, где стоят машина и её питание.','A loader holds its own 16×16 chunk rather than an arbitrary radius. The limit is three devices per player; shared quest progress does not increase it. Use F3+G to inspect boundaries around machinery and power.',True)
q('chunks','chunkcare','Проверить и убрать лишнее','Verify and Remove Unneeded Loaders','chunklimits','','Если шахта пересекает границу, одного устройства может не хватить для всех нужных частей. Проверьте работу издали и удалите ненужные загрузчики. Постоянно работающие машины и сущности нагружают сервер; загрузка чанка не означает появление игрока для всех игровых механик.','If a mine crosses a boundary, one loader may not cover all required parts. Check operation from afar and remove unneeded loaders. Always-running machines and entities cost server time; loading a chunk does not emulate a player for every mechanic.',True)

def dumps(obj, depth=0):
    # JSON syntax is a supported subset of the installed FTB SNBT parser.
    return json.dumps(obj,ensure_ascii=False,indent=2)

def build():
    revise(QUESTS)
    audit=json.loads((Path(__file__).parent/'server-evidence.json').read_text(encoding='utf-8'))
    models=set(audit['item_models'])
    keys={q['key'] for q in QUESTS}; assert len(keys)==len(QUESTS)
    for quest in QUESTS:
        assert set(quest['deps'])<=keys,quest['key']
        for item in quest['items']:
            assert item.startswith('minecraft:') or item in models,('Unverified item',item)
    visiting=set();visited=set();bykey={q['key']:q for q in QUESTS}
    def walk(k):
        assert k not in visiting,('cycle',k)
        if k in visited:return
        visiting.add(k)
        for d in bykey[k]['deps']:walk(d)
        visiting.remove(k);visited.add(k)
    for k in keys:walk(k)
    (OUT/'chapters').mkdir(parents=True,exist_ok=True);(OUT/'lang').mkdir(exist_ok=True)
    locales={'ru_ru':{},'en_us':{}}
    for lang,loc in locales.items():
        loc[f'chapter_group.{uid("group")}.title']='Create: Городское расширение' if lang=='ru_ru' else 'Create: City Expansion'
        loc['file.0000000000000001.title']='Create: Городское расширение' if lang=='ru_ru' else 'Create: City Expansion'
    ids=set()
    for ci,(ch,ru,en,icon) in enumerate(CHAPTERS):
        main=[q for q in QUESTS if q['ch']==ch and not q['side']]
        sides=[q for q in QUESTS if q['ch']==ch and q['side']]
        positions={k:(x*1.15,y*1.15) for k,(x,y) in POSITIONS.items()}
        nodes=[]
        for quest in [*main,*sides]:
            k=quest['key'];qid=uid('quest:'+k);ids.add(qid)
            tasks=[]
            for j,item in enumerate(quest['items']):
                tid=uid('task:'+k+':'+item);ids.add(tid)
                tasks.append(dict(id=tid,type='item',item={'id':item,'count':1},count=1,consume_items=False,only_from_crafting=False))
            if not tasks:
                tid=uid('task:'+k+':check');ids.add(tid);tasks=[dict(id=tid,type='checkmark')]
                locales['ru_ru'][f'task.{tid}.title']='Практика выполнена — отметить вручную'
                locales['en_us'][f'task.{tid}.title']='Practice completed — confirm manually'
            x,y=positions[k]
            node=dict(id=qid,x=x,y=y,dependencies=[uid('quest:'+d) for d in quest['deps']],tasks=tasks,rewards=[],shape='circle',size=1.0,optional=quest['side'])
            node['hide_dependency_lines']=False
            node['icon']={'id':ICONS.get(k,quest['items'][0] if quest['items'] else icon)}
            nodes.append(node)
            for lang,title,body in [('ru_ru',quest['ru'],quest['body_ru']),('en_us',quest['en'],quest['body_en'])]:
                loc=locales[lang];loc[f'quest.{qid}.title']=title
                loc[f'quest.{qid}.quest_subtitle']=('Дополнительно' if lang=='ru_ru' else 'Optional') if quest['side'] else ('Основной путь' if lang=='ru_ru' else 'Main path')
                tail=('Проверка наличия: предметы не расходуются. Готовая общая установка не требует повторного изготовления; при необходимости временно возьмите образец в инвентарь.' if lang=='ru_ru' else 'Possession check: items are not consumed. Shared equipment does not require duplicate crafting; temporarily carry a sample when needed.') if quest['items'] else ('Ручная проверка: выполните описанное действие и подтвердите его отметкой. Книга не проверяет это действие автоматически.' if lang=='ru_ru' else 'Manual check: perform the described practice and confirm it. The book does not automatically detect this action.')
                loc[f'quest.{qid}.quest_desc']=[body,'',tail]
        cid=uid('chapter:'+ch);ids.add(cid)
        chapter=dict(id=cid,filename='ccec_'+ch,group=uid('group'),order_index=ci,icon={'id':icon},default_hide_dependency_lines=False,default_quest_shape='circle',images=[],quest_links=[],quests=nodes)
        (OUT/'chapters'/('ccec_'+ch+'.snbt')).write_text(dumps(chapter)+'\n',encoding='utf-8')
        for lang,title in [('ru_ru',ru),('en_us',en)]:
            locales[lang][f'chapter.{cid}.title']=title
            locales[lang][f'chapter.{cid}.chapter_subtitle']=[('Связи показывают предпосылки. Боковые ветви — дополнительные занятия. Предметы не расходуются, наград ресурсами нет.' if lang=='ru_ru' else 'Connections show prerequisites. Side branches offer optional practice. Items are not consumed; no resource rewards.')]
    (OUT/'chapter_groups.snbt').write_text(dumps({'chapter_groups':[{'id':uid('group')} ]})+'\n',encoding='utf-8')
    (OUT/'data.snbt').write_text(dumps(dict(version=13,default_consume_items=False,default_autoclaim_rewards='disabled',default_reward_team=False,fallback_locale='en_us',progression_mode='linear',grid_scale=0.5,detection_delay=20,show_lock_icons=True,drop_loot_crates=False,disable_gui=False))+'\n',encoding='utf-8')
    for lang,loc in locales.items():(OUT/'lang'/(lang+'.snbt')).write_text(dumps(loc)+'\n',encoding='utf-8')
    assert set(locales['ru_ru'])==set(locales['en_us'])
    manifest=dict(quests=len(QUESTS),chapters=len(CHAPTERS),items=sorted({i for q in QUESTS for i in q['items']}),jars=audit['jars'],ids=sorted(ids|{uid('group')}),counts={ch:sum(q['ch']==ch for q in QUESTS) for ch,*_ in CHAPTERS},manual=sum(not q['items'] for q in QUESTS))
    (OUT.parent/'manifest.json').write_text(dumps(manifest)+'\n',encoding='utf-8')
    (OUT.parent/'quest-catalog.json').write_text(dumps(QUESTS)+'\n',encoding='utf-8')
    print(dumps({k:manifest[k] for k in ['quests','chapters','counts','manual']}))

if __name__=='__main__':build()
